package com.medicore.fulfillment.service; import com.medicore.fulfillment.dto.*; import com.medicore.fulfillment.entity.Fulfillment; import com.medicore.fulfillment.repository.FulfillmentRepository; import org.springframework.stereotype.Service; import java.util.Set; @Service public class FulfillmentService {private final FulfillmentRepository repository; public FulfillmentService(FulfillmentRepository repository){this.repository=repository;} public FulfillmentResponse create(FulfillmentRequest r){return response(repository.save(new Fulfillment(r.orderId())));} public FulfillmentResponse find(Long id){return response(repository.findById(id).orElseThrow(()->new IllegalArgumentException("Fulfillment not found")));} public FulfillmentResponse status(Long id,String s){if(!Set.of("PENDING","PACKED","SHIPPED","COMPLETED","CANCELLED").contains(s))throw new IllegalArgumentException("Invalid status");Fulfillment f=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Fulfillment not found"));f.setStatus(s);return response(repository.save(f));} private FulfillmentResponse response(Fulfillment f){return new FulfillmentResponse(f.getId(),f.getOrderId(),f.getStatus());}}
